package com.rustyvault.legacy;

import com.rustyvault.CustomerDirectory;
import java.sql.*;
import java.util.*;

public class LegacyCustomerDirectory implements CustomerDirectory {

    private final Connection conn;

    public LegacyCustomerDirectory(Connection conn) {
        this.conn = conn;
    }

    @Override
    public long addCustomer(String name, String city, long balanceCents) {
        if (name == null || name.isBlank() || city == null || city.isBlank() || balanceCents < 0) {
            throw new IllegalArgumentException("Invalid customer data");
        }
        String sql = "INSERT INTO customer (name, city, balance_cents) VALUES (?, ?, ?)";
        try (PreparedStatement ps = conn.prepareStatement(sql, Statement.RETURN_GENERATED_KEYS)) {
            ps.setString(1, name);
            ps.setString(2, city);
            ps.setLong(3, balanceCents);
            ps.executeUpdate();
            try (ResultSet rs = ps.getGeneratedKeys()) {
                if (rs.next()) {
                    return rs.getLong(1);
                }
                throw new IllegalStateException("No ID generated");
            }
        } catch (SQLException e) {
            throw new IllegalStateException("Database error: " + e.getMessage());
        }
    }

    @Override
    public List<String> findByName(String name) {
        if (name == null) throw new IllegalArgumentException("Name cannot be null");
        return query("SELECT id, name, city, balance_cents FROM customer WHERE name = ? ORDER BY id", name);
    }

    @Override
    public List<String> searchByNamePrefix(String prefix) {
        if (prefix == null) throw new IllegalArgumentException("Prefix cannot be null");
        String escaped = prefix.replace("\\", "\\\\").replace("%", "\\%").replace("_", "\\_");
        return query("SELECT id, name, city, balance_cents FROM customer WHERE UPPER(name) LIKE UPPER(?) ESCAPE '\\' ORDER BY id",
                escaped + "%");
    }

    @Override
    public List<String> list(String sortBy, boolean descending) {
        if (sortBy == null) throw new IllegalArgumentException("Sort key cannot be null");
        String column = switch (sortBy) {
            case "id" -> "id";
            case "name" -> "name";
            case "city" -> "city";
            case "balance" -> "balance_cents";
            default -> throw new IllegalArgumentException("Invalid sort key: " + sortBy);
        };
        String sql = "SELECT id, name, city, balance_cents FROM customer ORDER BY " + column + (descending ? " DESC" : " ASC") + ", id ASC";
        return query(sql);
    }

    @Override
    public String getById(String id) {
        validateNumeric(id);
        List<String> rows = query("SELECT id, name, city, balance_cents FROM customer WHERE id = ?", Long.parseLong(id));
        return rows.isEmpty() ? null : rows.get(0);
    }

    @Override
    public List<String> findByIds(List<String> ids) {
        if (ids == null) throw new IllegalArgumentException("IDs list cannot be null");
        List<Long> parsedIds = new ArrayList<>();
        for (String id : ids) {
            validateNumeric(id);
            parsedIds.add(Long.parseLong(id));
        }
        if (parsedIds.isEmpty()) return List.of();
        List<Long> uniqueSorted = parsedIds.stream().distinct().sorted().toList();
        String placeholders = String.join(",", Collections.nCopies(uniqueSorted.size(), "?"));
        return query("SELECT id, name, city, balance_cents FROM customer WHERE id IN (" + placeholders + ") ORDER BY id",
                uniqueSorted.toArray());
    }

    @Override
    public List<String> richerThan(String minBalanceCents) {
        validateNumeric(minBalanceCents);
        return query("SELECT id, name, city, balance_cents FROM customer WHERE balance_cents > ? ORDER BY id",
                Long.parseLong(minBalanceCents));
    }

    @Override
    public List<String> sameCityAs(String id) {
        validateNumeric(id);
        long customerId = Long.parseLong(id);
        String city = null;
        try (PreparedStatement ps = conn.prepareStatement("SELECT city FROM customer WHERE id = ?")) {
            ps.setLong(1, customerId);
            try (ResultSet rs = ps.executeQuery()) {
                if (rs.next()) city = rs.getString(1);
            }
        } catch (SQLException e) {
            throw new IllegalStateException("Database error: " + e.getMessage());
        }
        if (city == null) throw new IllegalArgumentException("Unknown customer ID: " + id);
        return query("SELECT id, name, city, balance_cents FROM customer WHERE city = ? AND id <> ? ORDER BY id",
                city, customerId);
    }

    @Override
    public int deleteByCity(String city) {
        if (city == null) throw new IllegalArgumentException("City cannot be null");
        try (PreparedStatement ps = conn.prepareStatement("DELETE FROM customer WHERE city = ?")) {
            ps.setString(1, city);
            return ps.executeUpdate();
        } catch (SQLException e) {
            throw new IllegalStateException("Database error: " + e.getMessage());
        }
    }

    @Override
    public int count() {
        try (PreparedStatement ps = conn.prepareStatement("SELECT COUNT(*) FROM customer")) {
            try (ResultSet rs = ps.executeQuery()) {
                if (rs.next()) return rs.getInt(1);
                return 0;
            }
        } catch (SQLException e) {
            throw new IllegalStateException("Database error: " + e.getMessage());
        }
    }

    private void validateNumeric(String s) {
        if (s == null || !s.matches("^[0-9]{1,18}$")) {
            throw new IllegalArgumentException("Invalid numeric input: " + s);
        }
    }

    private List<String> query(String sql, Object... params) {
        List<String> rows = new ArrayList<>();
        try (PreparedStatement ps = conn.prepareStatement(sql)) {
            for (int i = 0; i < params.length; i++) {
                ps.setObject(i + 1, params[i]);
            }
            try (ResultSet rs = ps.executeQuery()) {
                while (rs.next()) {
                    rows.add(rs.getLong(1) + "|" + rs.getString(2) + "|" + rs.getString(3) + "|" + rs.getLong(4));
                }
            }
        } catch (SQLException e) {
            throw new IllegalStateException("SQL ERROR: " + e.getMessage());
        }
        return rows;
    }
}
